              <Breadcrumbs.Link href="/" icon={<ShuiMark />}>
                SHUI
              </Breadcrumbs.Link>
              <Breadcrumbs.Separator />
              <Breadcrumbs.Link href="/admin">Administration</Breadcrumbs.Link>
