import { LinkButton, LayerCard } from "@cloudflare/kumo";
import type { ReactNode } from "react";

export function M1Layout({
  eyebrow,
  title,
  description,
  children,
  footer,
}: Readonly<{
  eyebrow: string;
  title: string;
  description: string;
  children: ReactNode;
  footer?: ReactNode;
}>) {
  return (
    <div className="relative isolate min-h-screen overflow-hidden bg-kumo-canvas">
      <div aria-hidden="true" className="m1-orbit m1-orbit-one" />
      <div aria-hidden="true" className="m1-orbit m1-orbit-two" />
      <header className="relative mx-auto flex max-w-6xl items-center justify-between px-5 py-6 sm:px-8">
        <LinkButton className="m1-wordmark" href="/" variant="ghost">
          SHUI<span>/</span>
        </LinkButton>
        <p className="hidden text-xs font-medium uppercase tracking-[0.22em] text-kumo-subtle sm:block">
          Identity control plane
        </p>
      </header>
      <main className="relative mx-auto grid w-full max-w-6xl gap-10 px-5 pb-16 pt-8 sm:px-8 sm:pt-16 lg:grid-cols-[minmax(0,0.8fr)_minmax(22rem,1fr)] lg:items-start lg:gap-20 lg:pt-24">
        <div className="max-w-xl">
          <p className="text-sm font-medium uppercase tracking-[0.18em] text-(--tangerine)">
            {eyebrow}
          </p>
          <h1 className="mt-5 max-w-lg font-display text-4xl font-semibold leading-[0.98] text-kumo-strong sm:text-6xl">
            {title}
          </h1>
          <p className="mt-6 max-w-md text-base leading-7 text-kumo-subtle">{description}</p>
          <div className="mt-10 hidden border-l border-(--tangerine)/40 pl-5 text-sm leading-6 text-kumo-subtle lg:block">
            One place for people, applications, and access decisions.
          </div>
        </div>
        <LayerCard className="m1-panel bg-kumo-elevated p-5 ring ring-kumo-line sm:p-7">
          {children}
          {footer ? <div className="mt-7 border-t border-kumo-hairline pt-5">{footer}</div> : null}
        </LayerCard>
      </main>
    </div>
  );
}

export function FormError({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <p className="text-sm text-(--m1-error)" role="alert">
      {children}
    </p>
  );
}

export function FormStatus({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <p className="text-sm text-kumo-brand" role="status">
      {children}
    </p>
  );
}
import { LinkButton } from "@cloudflare/kumo";

export function LandingPage() {
  return (
    <div className="relative isolate min-h-screen overflow-hidden bg-kumo-canvas">
      <div aria-hidden="true" className="m1-orbit m1-orbit-one" />
      <div aria-hidden="true" className="m1-orbit m1-orbit-two" />
      <header className="relative mx-auto flex max-w-6xl items-center justify-between px-5 py-6 sm:px-8">
        <LinkButton className="m1-wordmark" href="/" variant="ghost">
          SHUI<span>/</span>
        </LinkButton>
        <div className="flex items-center gap-2">
          <LinkButton className="text-sm" href="/sign-in" variant="ghost">
            Sign in
          </LinkButton>
        </div>
      </header>
      <main className="relative mx-auto grid max-w-6xl gap-12 px-5 pb-20 pt-20 sm:px-8 lg:grid-cols-[1fr_0.75fr] lg:items-end lg:pt-32">
        <div>
          <p className="text-sm font-medium uppercase tracking-[0.18em] text-(--tangerine)">
            Identity control plane
          </p>
          <h1 className="mt-5 max-w-3xl font-display text-5xl font-semibold leading-[0.92] text-kumo-strong sm:text-7xl">
            Access starts with a clear identity.
          </h1>
          <p className="mt-7 max-w-xl text-lg leading-8 text-kumo-subtle">
            Shui gives people and applications one deliberate place to authenticate, request access,
            and carry the right context downstream.
          </p>
          <div className="mt-10">
            <LinkButton className="justify-center text-sm" href="/sign-in" variant="primary">
              Sign in to Shui
            </LinkButton>
          </div>
        </div>
        <div className="grid gap-3 sm:grid-cols-3 lg:grid-cols-1">
          {[
            ["01", "Closed by default", "No public account creation after bootstrap."],
            ["02", "Invite with intent", "Every seat has an expiry and a single use."],
            ["03", "Revoke cleanly", "Disabled identities lose their sessions."],
          ].map(([number, title, description]) => (
            <div className="border-t border-kumo-line py-4" key={number}>
              <p className="text-xs font-medium tracking-[0.18em] text-(--tangerine)">{number}</p>
              <h2 className="mt-2 text-lg font-semibold text-kumo-strong">{title}</h2>
              <p className="mt-1 text-sm leading-6 text-kumo-subtle">{description}</p>
            </div>
          ))}
        </div>
      </main>
    </div>
  );
}
import { LayerCard, LinkButton } from "@cloudflare/kumo";

export function ForbiddenPage() {
  return (
    <section className="mx-auto max-w-xl px-5 py-14 sm:px-8 sm:py-20">
      <p className="text-sm font-medium text-(--tangerine)">Access control</p>
      <h1 className="mt-4 font-display text-4xl font-semibold leading-none text-kumo-strong sm:text-6xl">
        You do not have access.
      </h1>
      <LayerCard className="mt-10 bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
        <p className="text-sm leading-6 text-kumo-subtle">
          Your account is signed in, but its system role does not allow this administration area.
        </p>
        <div className="mt-6 flex flex-col gap-3 sm:flex-row">
          <LinkButton className="justify-center text-sm" href="/" variant="primary">
            Return home
          </LinkButton>
          <LinkButton className="justify-center text-sm" href="/sign-in" variant="ghost">
            Sign in as another user
          </LinkButton>
        </div>
      </LayerCard>
    </section>
  );
}
import { HeadContent, Scripts } from "@tanstack/react-router";
import type { ReactNode } from "react";

export function RootDocument({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <html data-mode="dark" lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}

